ALTER FUNCTION public.terminal_can(uuid,text) SECURITY INVOKER;
CREATE OR REPLACE FUNCTION public.tau_guard_pay_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR auth.role()='service_role' THEN RETURN NEW; END IF; IF NEW.is_active IS DISTINCT FROM OLD.is_active AND NOT public.terminal_can(auth.uid(),'terminal_autopay_toggle') THEN RAISE EXCEPTION 'Auto-pay Toggle required' USING ERRCODE='42501'; END IF; IF ((to_jsonb(NEW)-ARRAY['is_active','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['is_active','updated_at','updated_by']) OR (NEW.updated_by IS DISTINCT FROM OLD.updated_by AND NEW.is_active IS NOT DISTINCT FROM OLD.is_active)) AND NOT public.terminal_can(auth.uid(),'terminal_autopay_configure') THEN RAISE EXCEPTION 'Auto-pay Configure required to edit settings' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.tau_due_merchant_schedules() RETURNS SETOF public.p2p_merchant_schedules LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH clock AS (SELECT now() AS n,now() AT TIME ZONE 'Asia/Kolkata' AS local_now), windows AS (SELECT s.*, (d.day+s.start_time) AT TIME ZONE 'Asia/Kolkata' AS window_start,(d.day+s.end_time+CASE WHEN s.end_time<s.start_time THEN interval '1 day' ELSE interval '0 day' END) AT TIME ZONE 'Asia/Kolkata' AS window_end FROM public.p2p_merchant_schedules s CROSS JOIN clock c CROSS JOIN LATERAL (VALUES(c.local_now::date),(c.local_now::date-1)) d(day) WHERE s.is_active AND extract(dow FROM d.day)=s.day_of_week) SELECT s FROM public.p2p_merchant_schedules s JOIN windows w ON w.id=s.id CROSS JOIN clock c WHERE w.window_start<=c.n AND ((w.action='go_online' AND c.n<w.window_start+interval '1 day') OR (w.action<>'go_online' AND c.n<=w.window_end-interval '1 minute')) AND NOT EXISTS(SELECT 1 FROM public.p2p_merchant_schedule_runs r WHERE r.schedule_id=s.id AND r.occurrence_start=w.window_start); $$;